// Emulation of Python `bytes` objects using plain strings whose character
// codes represent byte values (inputs in this program are pure ASCII).

export class PyBytes {
  constructor(data) {
    this.data = data;
  }

  get length() {
    return this.data.length;
  }
}

// Equivalent of Python's str.encode('ascii'): every character must fit in
// 7 bits, otherwise Python raises UnicodeEncodeError and exits with code 1.
export function asciiEncode(text, lineNo) {
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code > 0x7f) {
      let chRepr;
      if (code <= 0xff) chRepr = '\\x' + code.toString(16).padStart(2, '0');
      else if (code <= 0xffff) chRepr = '\\u' + code.toString(16).padStart(4, '0');
      else chRepr = '\\U' + code.toString(16).padStart(8, '0');
      process.stderr.write('Traceback (most recent call last):\n');
      process.stderr.write(`  File "test12.py", line ${lineNo}, in <module>\n`);
      process.stderr.write(
        `UnicodeEncodeError: 'ascii' codec can't encode character '${chRepr}' ` +
        `in position ${i}: ordinal not in range(128)\n`
      );
      process.exit(1);
    }
  }
  return new PyBytes(text);
}

// Reproduces Python's repr() for a bytes object, character by character.
export function bytesRepr(data) {
  const hasSingle = data.includes("'");
  const hasDouble = data.includes('"');
  // Python prefers single quotes, switching to double quotes only when the
  // data contains a single quote but no double quote.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = 'b' + quote;
  for (let i = 0; i < data.length; i++) {
    const code = data.charCodeAt(i);
    const ch = data[i];
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (code >= 0x20 && code < 0x7f) out += ch;
    else out += '\\x' + code.toString(16).padStart(2, '0');
  }
  return out + quote;
}

// Bencode encoder/decoder, reimplemented from observed interface behavior.
// Supported value model:
//   - byte strings  -> PyBytes
//   - integers      -> BigInt (arbitrary precision, like Python int)
//   - lists         -> Array
//   - dictionaries  -> Map with PyBytes keys (preserves insertion order)

import { PyBytes } from './pybytes.mjs';

// Byte-wise lexicographic comparison (dictionary keys are sorted on encode).
function compareByteStrings(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const d = a.charCodeAt(i) - b.charCodeAt(i);
    if (d !== 0) return d;
  }
  return a.length - b.length;
}

export function encode(value) {
  if (value instanceof PyBytes) {
    return value.length + ':' + value.data;
  }
  if (typeof value === 'bigint' || typeof value === 'number') {
    return 'i' + value.toString() + 'e';
  }
  if (Array.isArray(value)) {
    let out = 'l';
    for (const item of value) out += encode(item);
    return out + 'e';
  }
  if (value instanceof Map) {
    const keys = [...value.keys()].sort((x, y) => compareByteStrings(x.data, y.data));
    let out = 'd';
    for (const key of keys) out += encode(key) + encode(value.get(key));
    return out + 'e';
  }
  throw new TypeError('unsupported type for bencode: ' + String(value));
}

export function decode(text) {
  let pos = 0;

  function parse() {
    const ch = text[pos];
    if (ch === 'i') {
      const end = text.indexOf('e', pos);
      const num = BigInt(text.slice(pos + 1, end));
      pos = end + 1;
      return num;
    }
    if (ch === 'l') {
      pos++;
      const list = [];
      while (text[pos] !== 'e') list.push(parse());
      pos++;
      return list;
    }
    if (ch === 'd') {
      pos++;
      const dict = new Map();
      while (text[pos] !== 'e') {
        const key = parse();
        dict.set(key, parse());
      }
      pos++;
      return dict;
    }
    if (ch >= '0' && ch <= '9') {
      const colon = text.indexOf(':', pos);
      const len = Number(text.slice(pos, colon));
      pos = colon + 1;
      const data = text.slice(pos, pos + len);
      pos += len;
      return new PyBytes(data);
    }
    throw new Error('invalid bencode data at position ' + pos);
  }

  return parse();
}

// Reproduces Python's repr()/print() formatting for the value model used
// by this program (bytes, ints, lists, dicts).

import { PyBytes, bytesRepr } from './pybytes.mjs';

export function pyStrRepr(text) {
  // Same quoting/escaping rules as bytes repr, without the leading "b".
  return bytesRepr(text).slice(1);
}

export function pyRepr(value) {
  if (value instanceof PyBytes) return bytesRepr(value.data);
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return String(value);
  if (typeof value === 'string') return pyStrRepr(value);
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (value instanceof Map) {
    const parts = [];
    for (const [k, v] of value) parts.push(pyRepr(k) + ': ' + pyRepr(v));
    return '{' + parts.join(', ') + '}';
  }
  return String(value);
}

// Minimal reimplementation of the argparse behavior used by the source
// script: required --name options taking one value, with `str` and `int`
// types, supporting both "--name value" and "--name=value" forms.

import { pyStrRepr } from './pyrepr.mjs';

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.specs = [];
  }

  addArgument(name, options = {}) {
    this.specs.push({
      name,
      type: options.type || 'str',
      required: options.required !== false,
    });
  }

  usage() {
    let out = `usage: ${this.prog} [-h]`;
    for (const spec of this.specs) out += ` --${spec.name} ${spec.name.toUpperCase()}`;
    return out;
  }

  error(message) {
    process.stderr.write(this.usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parse(argv) {
    const values = {};
    const byName = new Map(this.specs.map((s) => [s.name, s]));
    const unrecognized = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        process.stdout.write(this.usage() + '\n');
        process.exit(0);
      }
      let name = null;
      let inlineValue = null;
      if (token.startsWith('--')) {
        const eq = token.indexOf('=');
        if (eq !== -1) {
          name = token.slice(2, eq);
          inlineValue = token.slice(eq + 1);
        } else {
          name = token.slice(2);
        }
      }
      const spec = name !== null ? byName.get(name) : undefined;
      if (!spec) {
        unrecognized.push(token);
        continue;
      }
      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else if (i + 1 < argv.length) {
        raw = argv[++i];
      } else {
        this.error(`argument --${spec.name}: expected one argument`);
      }
      if (spec.type === 'int') {
        const trimmed = raw.trim();
        if (!/^[+-]?\d+$/.test(trimmed)) {
          this.error(`argument --${spec.name}: invalid int value: ${pyStrRepr(raw)}`);
        }
        values[spec.name] = BigInt(trimmed);
      } else {
        values[spec.name] = raw;
      }
    }

    if (unrecognized.length > 0) {
      this.error('unrecognized arguments: ' + unrecognized.join(' '));
    }

    const missing = this.specs.filter((s) => s.required && !(s.name in values));
    if (missing.length > 0) {
      this.error(
        'the following arguments are required: ' +
        missing.map((s) => '--' + s.name).join(', ')
      );
    }

    return values;
  }
}

